function createVoiceRacingGame(canvasId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;
    canvas.width = 500;
    canvas.height = 500;
    const ctx = canvas.getContext('2d');

    const uiContainer = document.createElement('div');
    document.body.appendChild(uiContainer);
    const startBtn = document.createElement('button');
    startBtn.textContent = 'Start Race';
    uiContainer.appendChild(startBtn);
    const muteBtn = document.createElement('button');
    muteBtn.textContent = 'Mute';
    uiContainer.appendChild(muteBtn);
    const volMeter = document.createElement('div');
    volMeter.style.width = '200px';
    volMeter.style.height = '20px';
    volMeter.style.border = '1px solid #000';
    volMeter.style.background = '#ddd';
    volMeter.style.marginTop = '10px';
    const volFill = document.createElement('div');
    volFill.style.height = '100%';
    volFill.style.width = '0%';
    volFill.style.background = '#0a0';
    volMeter.appendChild(volFill);
    uiContainer.appendChild(volMeter);
    const info = document.createElement('div');
    info.style.marginTop = '10px';
    uiContainer.appendChild(info);

    const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    let analyser, dataArray, sourceNode, gainNode;
    let volLevel = 0;
    let micStream = null;
    let muted = false;

    const track = {
        cx: canvas.width / 2,
        cy: canvas.height / 2,
        radius: 180,
        innerRadius: 140,
        outerRadius: 200,
        obstacles: [
            { x: 250, y: 120, w: 30, h: 30 },
            { x: 380, y: 250, w: 30, h: 30 },
            { x: 250, y: 380, w: 30, h: 30 },
            { x: 120, y: 250, w: 30, h: 30 }
        ]
    };

    const car = {
        angle: 0,
        speed: 0,
        maxSpeed: 4,
        size: 12,
        x: 0,
        y: 0
    };

    let raceRunning = false;
    let startTime = 0;
    let lastLapTime = 0;
    let bestLap = null;
    let laps = 0;
    const targetLaps = 3;

    function initAudio() {
        navigator.mediaDevices.getUserMedia({ audio: true })
            .then(stream => {
                micStream = stream;
                sourceNode = audioCtx.createMediaStreamSource(stream);
                gainNode = audioCtx.createGain();
                analyser = audioCtx.createAnalyser();
                analyser.fftSize = 256;
                const bufferLen = analyser.frequencyBinCount;
                dataArray = new Uint8Array(bufferLen);
                sourceNode.connect(gainNode).connect(analyser).connect(audioCtx.destination);
                updateVolume();
            })
            .catch(() => {
                info.textContent = 'Microphone access denied.';
            });
    }

    function updateVolume() {
        if (!analyser) return;
        analyser.getByteTimeDomainData(dataArray);
        let sum = 0;
        for (let i = 0; i < dataArray.length; i++) {
            const v = (dataArray[i] - 128) / 128;
            sum += v * v;
        }
        const rms = Math.sqrt(sum / dataArray.length);
        volLevel = muted ? 0 : rms;
        volFill.style.width = Math.min(1, volLevel * 5) * 100 + '%';
        requestAnimationFrame(updateVolume);
    }

    function resetRace() {
        car.angle = 0;
        car.speed = 0;
        laps = 0;
        lastLapTime = 0;
        startTime = performance.now();
        raceRunning = true;
        info.textContent = '';
    }

    function drawTrack() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.strokeStyle = '#555';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(track.cx, track.cy, track.outerRadius, 0, Math.PI * 2);
        ctx.stroke();
        ctx.beginPath();
        ctx.arc(track.cx, track.cy, track.innerRadius, 0, Math.PI * 2);
        ctx.stroke();
        ctx.fillStyle = '#777';
        track.obstacles.forEach(ob => {
            ctx.fillRect(ob.x - ob.w / 2, ob.y - ob.h / 2, ob.w, ob.h);
        });
    }

    function drawCar() {
        const r = track.radius;
        car.x = track.cx + r * Math.cos(car.angle);
        car.y = track.cy + r * Math.sin(car.angle);
        ctx.save();
        ctx.translate(car.x, car.y);
        ctx.rotate(car.angle + Math.PI / 2);
        ctx.fillStyle = '#f00';
        ctx.beginPath();
        ctx.moveTo(0, -car.size);
        ctx.lineTo(car.size / 2, car.size);
        ctx.lineTo(-car.size / 2, car.size);
        ctx.closePath();
        ctx.fill();
        ctx.restore();
    }

    function checkCrash() {
        const dx = car.x - track.cx;
        const dy = car.y - track.cy;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < track.innerRadius || dist > track.outerRadius) {
            return true;
        }
        for (let ob of track.obstacles) {
            if (Math.abs(car.x - ob.x) < ob.w / 2 + car.size && Math.abs(car.y - ob.y) < ob.h / 2 + car.size) {
                return true;
            }
        }
        return false;
    }

    function handleCrash() {
        const severity = car.speed / car.maxSpeed;
        const penalty = severity > 0.7 ? 3000 : 1000;
        raceRunning = false;
        info.textContent = 'Crashed! Restarting in ' + penalty / 1000 + 's';
        setTimeout(() => {
            resetRace();
        }, penalty);
    }

    function updateRace(dt) {
        if (!raceRunning) return;
        car.speed = Math.min(car.maxSpeed, car.maxSpeed * volLevel * 2);
        const angularVelocity = car.speed / track.radius;
        car.angle += angularVelocity;
        if (car.angle >= Math.PI * 2) {
            car.angle -= Math.PI * 2;
            lapCompleted();
        }
        if (checkCrash()) {
            handleCrash();
        }
    }

    function lapCompleted() {
        const now = performance.now();
        const lapTime = now - (lastLapTime || startTime);
        lastLapTime = now;
        laps++;
        if (!bestLap || lapTime < bestLap) bestLap = lapTime;
        info.textContent = `Lap ${laps}: ${(lapTime / 1000).toFixed(2)}s | Best: ${(bestLap / 1000).toFixed(2)}s`;
        if (laps >= targetLaps) {
            raceRunning = false;
            celebrate();
        }
    }

    function celebrate() {
        const particles = [];
        for (let i = 0; i < 100; i++) {
            particles.push({
                x: track.cx,
                y: track.cy,
                vx: (Math.random() - 0.5) * 4,
                vy: (Math.random() - 0.5) * 4,
                life: 60
            });
        }
        function drawConfetti() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            drawTrack();
            particles.forEach(p => {
                ctx.fillStyle = `hsl(${Math.random() * 360},80%,60%)`;
                ctx.fillRect(p.x, p.y, 4, 4);
                p.x += p.vx;
                p.y += p.vy;
                p.life--;
            });
            particles.filter(p => p.life > 0);
            if (particles.some(p => p.life > 0)) {
                requestAnimationFrame(drawConfetti);
            } else {
                resetRace();
            }
        }
        drawConfetti();
    }

    let lastTime = performance.now();
    function gameLoop(now) {
        const dt = now - lastTime;
        lastTime = now;
        drawTrack();
        updateRace(dt);
        drawCar();
        requestAnimationFrame(gameLoop);
    }

    startBtn.onclick = () => {
        if (audioCtx.state === 'suspended') audioCtx.resume();
        if (!micStream) initAudio();
        resetRace();
    };
    muteBtn.onclick = () => {
        muted = !muted;
        muteBtn.textContent = muted ? 'Unmute' : 'Mute';
    };
    requestAnimationFrame(gameLoop);
}
